/** urn:corpus:subscriptions:subscription:operation:announce_trial_end — ensures: output.trial_will_end_sent_at is present and output.trial_will_end_sent_at = now */
export const SubscriptionAnnounceTrialEndEnsures1 = (p: { input: SubscriptionLookup; current: SubscriptionSubscription; now: string; output: SubscriptionSubscription }): boolean =>
  (p.output.trial_will_end_sent_at !== undefined && Date.parse((p.output.trial_will_end_sent_at as string)) === Date.parse((p.now as string)));

/** urn:corpus:subscriptions:subscription:operation:announce_trial_end — ensures: current.trial_end is absent or output.trial_end is present and output.trial_end = current.trial_end */
export const SubscriptionAnnounceTrialEndEnsures2 = (p: { input: SubscriptionLookup; current: SubscriptionSubscription; output: SubscriptionSubscription }): boolean =>
  (p.current.trial_end === undefined || (p.output.trial_end !== undefined && (p.output.trial_end as string) === (p.current.trial_end as string)));

/** urn:corpus:subscriptions:subscription:operation:announce_trial_end — ensures: event.subscription_id = output.subscription_id */
export const SubscriptionAnnounceTrialEndEnsures3 = (p: { input: SubscriptionLookup; current: SubscriptionSubscription; output: SubscriptionSubscription; event: SubscriptionTrialWillEnd }): boolean =>
  (p.event?.subscription_id as string) === (p.output.subscription_id as string);

/** urn:corpus:subscriptions:subscription:operation:announce_trial_end — due: current.trial_will_end_sent_at is absent and current.trial_end is present and today >= current.trial_end - 3 */
export const SubscriptionAnnounceTrialEndDue1 = (p: { input: SubscriptionLookup; current: SubscriptionSubscription; today: string }): boolean =>
  ((p.current.trial_will_end_sent_at === undefined && p.current.trial_end !== undefined) && epochDay((p.today as string)) >= (epochDay((p.current.trial_end as string)) - 3));

